package com.infoviaan.basic.SwitchCase;

public class SwitchString {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		String name = "Govind";
		
		switch(name) {
		case "Govind" :
			System.out.println("Rajgarh , Mastikhor , & Inteligent ");
			break;
		case "Akshat" :
			System.out.println("Indori , Nalayak , & Jyda nhi h Inteligent ");
			break;
		case "Rizwan" :
			System.out.println("Bhihari , & Thoda sa Inteligent ");
			break;
		default:
			System.out.println("Not Found");
		}
	}

}
